const browserPluginRoot =
  process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { join } = await import("node:path");
const { pathToFileURL } = await import("node:url");
const { setupBrowserRuntime } = await import(
  pathToFileURL(join(browserPluginRoot, "scripts", "browser-client.mjs")).href
);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.getForUrl("http://localhost:3000/");
const tabs = await browser.tabs.list();
const tab = await browser.tabs.get(tabs[0].id);
await tab.goto("http://localhost:3000/drama/1/play?ep=1");
await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
await tab.playwright.getByText("选集").first().waitFor({ state: "visible", timeoutMs: 3000 });
await tab.playwright.waitForTimeout(1200);
// R2a: 点击第 3 集按钮切集（记录是 ep2/7s，?ep=1 显式存在不触发续播）
const clicked = await tab.playwright.evaluate(() => {
  const h2 = [...document.querySelectorAll("h2")].find((el) => el.textContent && el.textContent.trim() === "选集");
  const buttons = h2 && h2.nextElementSibling ? [...h2.nextElementSibling.querySelectorAll("button")] : [];
  const target = buttons.find((b) => (b.textContent || "").replace("✓", "").trim() === "3");
  if (!target) return false;
  target.click();
  return true;
});
await tab.playwright.waitForTimeout(600);
const afterClick = await tab.url();
// R2b: 键盘 ↓ 切到下一集（IAB 物理按键不可用，派发等价 KeyboardEvent）
await tab.playwright.evaluate(() => {
  window.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }));
});
await tab.playwright.waitForTimeout(600);
const afterKey = await tab.url();
nodeRepl.write(`R2 按钮切集 click=${clicked}: ${afterClick}\nR2 键盘↓: ${afterKey}\n`);
afterClick.includes("?ep=3") && afterKey.includes("?ep=4");

